+		} else if (what == "extend_end_bone") {
+			set_extend_end_bone(which, p_value);
+		} else if (what == "twist_from_rest") {
+			set_twist_from_rest(which, p_value);
+		} else if (what == "twist_from") {
+			set_twist_from(which, p_value);
